"""Shared helpers for the evaluation suite: benchmark loading and report writing."""

import json
from datetime import UTC, datetime
from pathlib import Path
from typing import Any

import httpx

from app.core.config import get_settings
from synthetic_data.generator.models import BenchmarkCase

REPORTS_DIR = Path(__file__).resolve().parent / "reports"
BENCHMARK_DIR = Path(__file__).resolve().parent.parent / "synthetic_data"


def load_benchmark_cases(benchmark_dir: Path | None = None) -> list[BenchmarkCase]:
    """Load ground-truth cases generated by `python -m synthetic_data.generator`."""
    ground_truth = (benchmark_dir or BENCHMARK_DIR) / "ground_truth"
    case_files = sorted(ground_truth.glob("case_*.json"))
    if not case_files:
        raise FileNotFoundError(
            f"No benchmark cases found under {ground_truth}. "
            "Run: python -m synthetic_data.generator --seed 42 --cases 30"
        )
    return [BenchmarkCase.model_validate_json(p.read_text(encoding="utf-8")) for p in case_files]


def case_documents_dir(case: BenchmarkCase, benchmark_dir: Path | None = None) -> Path:
    return (benchmark_dir or BENCHMARK_DIR) / "documents" / case.case_id


async def ollama_available() -> bool:
    settings = get_settings()
    try:
        async with httpx.AsyncClient(base_url=settings.ollama_base_url, timeout=5.0) as client:
            response = await client.get("/api/tags")
            response.raise_for_status()
    except (httpx.HTTPError, OSError):
        return False
    return True


def write_report(name: str, payload: dict[str, Any], markdown: str) -> tuple[Path, Path]:
    """Write one evaluation's JSON + Markdown report and return both paths."""
    REPORTS_DIR.mkdir(parents=True, exist_ok=True)
    payload = {
        "eval": name,
        "generated_at": datetime.now(UTC).isoformat(timespec="seconds"),
        **payload,
    }
    json_path = REPORTS_DIR / f"{name}_latest.json"
    md_path = REPORTS_DIR / f"{name}_latest.md"
    json_path.write_text(json.dumps(payload, indent=2) + "\n", encoding="utf-8")
    md_path.write_text(markdown.rstrip() + "\n", encoding="utf-8")
    return json_path, md_path


def markdown_table(headers: list[str], rows: list[list[str]]) -> str:
    lines = [
        "| " + " | ".join(headers) + " |",
        "| " + " | ".join("---" for _ in headers) + " |",
    ]
    lines.extend("| " + " | ".join(row) + " |" for row in rows)
    return "\n".join(lines)


def precision_recall_f1(tp: int, fp: int, fn: int) -> dict[str, float]:
    precision = tp / (tp + fp) if tp + fp else 0.0
    recall = tp / (tp + fn) if tp + fn else 0.0
    f1 = 2 * precision * recall / (precision + recall) if precision + recall else 0.0
    return {"precision": round(precision, 4), "recall": round(recall, 4), "f1": round(f1, 4)}
